const int trackerPin = 7;

void setup() {
  pinMode(trackerPin, INPUT);
  Serial.begin(9600);
}

void loop() {
  int state = digitalRead(trackerPin);
  if (state == HIGH) {
    Serial.println("BLACK LINE DETECTED");
  } else {
    Serial.println("White Surface");
  }
  delay(100);
}
